#!/bin/bash
# Hand-written (not generated by `booth config`, which leaves this file alone).
#
# Let the booth's gpg use the host's gpg-agent, so pinentry and the passphrase cache stay on the
# host. config.toml mounts the host agent's main socket, ${XDG_RUNTIME_DIR}/gnupg/S.gpg-agent, at
# the same path in the booth, where the booth's gpg looks. Not the restricted extra socket: the
# agent keeps a passphrase cache of its own for that one, so unlocking on the host would not
# reach the booth. Restricting it would guard little here anyway: ~/.gnupg is mounted as well.
#
# Docker creates the folder above that socket owned by root, and gpg ignores a socket folder it
# does not own (it would start an agent of its own instead), so give the folder to coder.
#
# The host agent's pinentry runs on the host, but would be told the booth's terminal, which on the
# host is some other one (or none). So every booth shell gets GPG_TTY=/dev/null: a passphrase the
# host agent has not cached makes gpg fail ("Inappropriate ioctl for device") instead of asking
# on a terminal nobody is looking at. Unlock on the host first (`just claude` does it).
#
# Nothing changes when the socket is not mounted (on macOS, or with XDG_RUNTIME_DIR unset on the
# host): the booth's gpg then runs its own agent and asks in the booth. Sourced with `set -e`
# beside the other startups: it runs in a subshell and never fails the start.
(
    dir="/run/user/$(id -u)/gnupg"
    [ -S "$dir/S.gpg-agent" ] || exit 0
    if [ ! -O "$dir" ]; then
        sudo chown "$(id -u):$(id -g)" "$dir" && sudo chmod 700 "$dir"
    fi
    printf '%s\n' '# Written by .booth/startups/20-host-gpg-agent--startup.sh: gpg uses the host agent.' \
                  'export GPG_TTY=/dev/null' \
        | sudo tee /etc/profile.d/95-host-gpg-agent--profile.sh >/dev/null
) || true
